from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if not left or not right or len(left[0]) != len(right[0]):
                continue

            def minority_color(part):
                counts = Counter(x for row in part for x in row)
                return min(counts, key=counts.get)

            bg = minority_color(left)
            marker = minority_color(right)
            return [[3 if right[r][j] == marker else bg
                     for j in range(len(right[0]))] for r in range(h)]

    for r in range(h):
        if len(set(grid[r])) == 1:
            top, bottom = grid[:r], grid[r + 1:]
            if not top or not bottom:
                continue

            def minority_color(part):
                counts = Counter(x for row in part for x in row)
                return min(counts, key=counts.get)

            bg = minority_color(top)
            marker = minority_color(bottom)
            return [[3 if bottom[i][j] == marker else bg
                     for j in range(w)] for i in range(len(bottom))]

    return grid
